class GoogleAd(BaseModel):
    ad_title: str
    ad_description: str

class OutputGoogleAdList(BaseModel):
    copies: List[GoogleAd]

class InputGrowthIdea(BaseModel):
    name: constr(strip_whitespace=True, strict=True, min_length=2, max_length=100) = Field(...)
    description: constr(strip_whitespace=True, strict=True, min_length=2, max_length=400) = Field(...)
    target_keywords: constr(strip_whitespace=True, strict=True, min_length=2, max_length=100) = Field(...)
    target_audience: constr(strip_whitespace=True, strict=True, min_length=2, max_length=100) = Field(...)

class GrowthIdea(BaseModel):
    idea: str

class OutputGrowthIdeaList(BaseModel):
    copies: List[GrowthIdea]


#------- Endpoints ----------

class ContentType(str, Enum):
    google_ads = "google-ads"
    growthideas = "growth-ideas"

content_types = {
    "google-ads": {
        "input": InputGoogleAd,
        "output": OutputGoogleAdList,
    },
    "growth-ideas": {
        "input": InputGrowthIdea,
        "output": OutputGrowthIdeaList,
    }
}

@app.post("/v1/content/short/{content_type}/", response_model=OutputGrowthIdeaList, tags=["content"])
async def generate_content(input_data: InputGrowthIdea, content_type: ContentType):
    if content_type == "google-ads":
        output = [
            {
                "ad_description": "Get the copy you need in seconds without any hassle. Create marketing-ready content for landing pages, product descriptions, blog posts and ads with AI. Super Fast. Pre-written Content.",
                "ad_title": "Best Ai Writer Writesonic - Online Copywriting",
            },
            {
                "ad_description": "Writesonic Makes Writing High-Performing Landing Pages, Product Descriptions, Ads And Blog Posts Super Easy And Fast. Use Our Artificial Intelligence To Create Perfect Content In Seconds. Try Writesonic For Free Now!",
                "ad_title": "Ai Copywriter - Creates High-Pricing Landing Pages",
            }
        ]
    else:
        output = [
            {
                "idea": "Create a content marketing course that teaches marketers how to write high-performing content and use the power of AI to create content.",
            },
        ]
    print(output)
    
    return {"copies": output}
```

### Description
I am using the ContentType Enum model to dynamically generate the endpoints based on the path parameter.
How can I dynamically switch the input and response models based on the given path parameter?

For example:
- if the content_type is "google-ads", I would like to use the `InputGoogleAd` input model and `OutputGoogleAdList` response model.
- Similarly, if the content_type is "growth-ideas", I would like to use the `InputGrowthIdea` input model and `OutputGrowthIdeaList` response model.

**How can I do this in the same function without having to create n different functions for n possible path parameters?**

### Environment

* OS: macOS
* FastAPI Version: 0.63.0

* Python version: 3.7

